// Menu-only depth-buffer renderer. Flight retains the tested Canvas clipping path.
let previewGPU=null,previewGPUFailed=false;
function createPreviewGPU(){if(previewGPU||previewGPUFailed)return previewGPU;try{const canvas=document.createElement('canvas');canvas.width=canvas.height=640;const gl=canvas.getContext('webgl',{alpha:true,antialias:true,premultipliedAlpha:true,preserveDrawingBuffer:true});if(!gl||typeof gl.createShader!=='function'){previewGPUFailed=true;return null}const compile=(type,code)=>{const s=gl.createShader(type);gl.shaderSource(s,code);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s},program=gl.createProgram();gl.attachShader(program,compile(gl.VERTEX_SHADER,'attribute vec3 position;attribute vec4 color;attribute vec2 uv;varying vec4 c;varying vec2 v;void main(){gl_Position=vec4(position,1.0);c=color;v=uv;}'));gl.attachShader(program,compile(gl.FRAGMENT_SHADER,'precision mediump float;uniform sampler2D image;uniform float textured;varying vec4 c;varying vec2 v;void main(){vec4 t=texture2D(image,v);gl_FragColor=vec4(mix(c.rgb,t.rgb,t.a*textured),c.a);}'));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Preview shader link');const buffer=gl.createBuffer();gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);for(const [name,n,offset]of [['position',3,0],['color',4,12],['uv',2,28]]){const loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,n,gl.FLOAT,false,36,offset)}gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);gl.viewport(0,0,640,640);const fallback=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,fallback);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([255,255,255,255]));previewGPU={canvas,gl,program,buffer,textured:gl.getUniformLocation(program,'textured'),textures:new Map(),fallback};canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();previewGPUFailed=true;previewGPU=null});return previewGPU}catch(e){previewGPUFailed=true;return null}}
function previewFaceVertices(face,materials,project,view,f){const vs=face.vertices,a=vs[0],b=vs[1],c=vs[2],u=b.map((n,i)=>n-a[i]),v=c.map((n,i)=>n-a[i]),normal=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],length=Math.hypot(...normal)||1,light=face.uv?1:.6+.4*Math.abs((-normal[0]*.45-normal[1]*.3+normal[2]*.84)/length),hex=materials[face.material]||'#607b91',rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255*light),alpha=face.material==='flame'?.65:face.material==='trail'?.72*face.opacity:1,out=[];for(let i=1;i<vs.length-1;i++)for(const j of [0,i,i+1]){const point=project(vs[j]),uv=face.uv?.[j];out.push(point[0]/320,-point[1]/320,-(vs[j][1]*view+vs[j][2]*f)/300,...rgb,alpha,uv?(uv[0]*4+56)/512:0,uv?(uv[1]*4+56)/512:0)}return out}
function drawDepthShipPreview(g,faces,materials,id,project,view,f){if(!['main','shop'].includes(menuScreen)||state!=='menu')return false;const gpu=createPreviewGPU();if(!gpu)return false;const {gl,program}=gpu;gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,gpu.buffer);gl.depthMask(true);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const groups=[[],[],[],[]];for(const face of faces)groups[face.material==='flame'||face.material==='trail'?3:face.uv?(face.material==='under'?2:1):0].push(face);for(let group=0;group<4;group++){const vertices=groups[group].flatMap(face=>previewFaceVertices(face,materials,project,view,f));if(!vertices.length)continue;let texture=gpu.fallback;if(group===1||group===2){const key=id+':'+cosmeticChoice('paint')+':'+group;if(!gpu.textures.has(key)){if(gpu.textures.size>=16){const first=gpu.textures.keys().next().value;gl.deleteTexture(gpu.textures.get(first));gpu.textures.delete(first)}const tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,solidShipTexture(id,group===2));gpu.textures.set(key,tex)}texture=gpu.textures.get(key)}gl.bindTexture(gl.TEXTURE_2D,texture);gl.uniform1f(gpu.textured,group===1||group===2?1:0);gl.depthMask(group!==3);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.DYNAMIC_DRAW);gl.drawArrays(gl.TRIANGLES,0,vertices.length/9)}gl.depthMask(true);g.drawImage(gpu.canvas,-320,-320);return true}
